-- ============================================================
-- 京町家・伝統建築（テーマID: 21, category_id: 5）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(5, 21, '京都の伝統的な町家が「うなぎの寝床」と呼ばれる理由はどれか。', '木材が細く長いから', '間口が狭く奥行きが深い形状から', '地下室が発達しているから', '屋根が極端に低いから', 1, '京町家は間口（道路に面した幅）が狭く、奥行きが非常に深い造りが特徴です。江戸時代に間口の幅で税（間口税）が課せられたため、間口を狭くして奥へ長く伸びる構造が発達しました。「うなぎの寝床」はこの形状を例えた表現です。', 1, false),
(5, 21, '京町家の入口から土間の奥まで続く細長い通路を何と呼ぶか。', '濡れ縁', '通り庭（とおりにわ）', '坪庭', 'ミセ', 1, '通り庭（とおりにわ）は京町家の土間を入口から奥まで通り抜けられる土間通路です。かまどや作業場として使われ、採光・通風の機能も担っています。通り庭の上部は「火袋（ひぶくろ）」という吹き抜けになっていることが多いです。', 1, false),
(5, 21, '京町家で、店先に設けられた商売をするためのスペースを何と呼ぶか。', 'ミセ（店）', 'ナカノマ（中の間）', 'デイ（出居）', 'ザシキ（座敷）', 0, 'ミセ（店）は京町家の通りに面した部分で、商売を行うための空間です。土間に板間を設けた構造が多く、格子越しに商品を見せる形式も見られます。', 1, false),
(5, 21, '京町家で「坪庭（つぼにわ）」が設けられる主な目的はどれか。', '野菜を栽培するため', '採光・通風・景観のため', '来客用の駐車スペースとして', '神祭りを行うため', 1, '坪庭は京町家の中に設けられた小さな中庭で、主に採光・通風の確保と景観（鑑賞）のために設けられます。うなぎの寝床の暗くなりがちな中間部分に光と風を取り込む機能があります。', 1, false),
(5, 21, '京町家の外壁に見られる格子（こうし）のうち、繊維・染物業の家に多い細かい縦格子の名称はどれか。', '本格子', '千本格子（せんぼんごうし）', '紅殻格子（べんがらごうし）', '犬矢来（いぬやらい）', 1, '千本格子（せんぼんごうし）は細かく並んだ縦格子で、西陣の機屋（はたや）など繊維業の家に多く見られます。外から中が見えにくく、中からは外が見やすい機能を持っています。', 2, false),
(5, 21, '京町家の正面下部に設けられた、竹などで作った半円形の防御・装飾物を何と呼ぶか。', '犬矢来（いぬやらい）', '海鼠壁（なまこかべ）', '土塀', '格子', 0, '犬矢来（いぬやらい）は京町家の外壁下部に設けられた竹・割竹などで作った半円形の囲いです。犬などの動物や通行人が壁に触れるのを防ぐ目的がありますが、現在は京都の町並みを特徴づける景観要素として知られています。', 1, false),
(5, 21, '「紅殻格子（べんがらごうし）」の「紅殻（べんがら）」とはどのような色のものか。', '黄色い顔料', '赤茶色（酸化鉄系）の顔料', '緑色の顔料', '黒色の顔料', 1, '紅殻（べんがら）は酸化鉄（Fe₂O₃）を主成分とする赤茶色の顔料です。紅殻格子は紅殻色に塗られた格子で、主に花街・茶屋・商家などに見られます。「べんがら色」は京都の町並みを象徴する色として知られています。', 2, false),
(5, 21, '京都で「庇（ひさし）」が発達した理由として最も適切なのはどれか。', '雪対策', '夏の強い日差しと雨対策', '防犯のため', '意匠（デザイン）上の理由のみ', 1, '京都の夏は猛暑・多雨のため、深い庇（ひさし）で日差しと雨を遮る機能が発達しました。庇は軒が深く張り出しており、縁側・格子の保護にもなります。「軒の深い京都の町家」は夏の暮らしに適した知恵です。', 2, false),
(5, 21, '京都で「仕舞屋（しもたや）」とはどのような町家を指すか。', '廃業した商家の建物', '住居専用で商売を行っていない町家', '武家屋敷の建物', '貸し家（賃貸）として使われる町家', 1, '仕舞屋（しもたや）は商売（店）を持たず、純粋に住居として使われる京町家のことです。格子はなく、一般的な民家の外観を持ちます。「仕舞い」＝商売をしていない、という意味から名付けられています。', 2, false),
(5, 21, '京都市が「京町家の保全及び継承に関する条例」を施行したのはいつか。', '2000年（平成12年）', '2010年（平成22年）', '2017年（平成29年）', '2022年（令和4年）', 2, '京都市は2017年（平成29年）に「京都市京町家の保全及び継承に関する条例」を全国に先駆けて制定・施行しました。急速に失われていく京町家を「市民共有の財産」として保全するための法的基盤を整備しました。', 2, false),
(5, 21, '「西陣の町家」に多く見られる「表屋造り（おもてやづくり）」とはどのような形式か。', '表（道路沿い）に蔵を設ける形式', '道路沿いに独立した店舗棟を持つ形式', '表面をタイル張りにした近代的な形式', '正面に庭を設ける形式', 1, '表屋造り（おもてやづくり）は道路に面した位置に独立した店舗棟（表屋）を設け、その奥に住居棟を配置する形式です。表と奥が分離した点が特徴で、西陣の機業（はたや）など大きな商家に見られます。', 3, false),
(5, 21, '京都の伝統的な町並み保存地区「産寧坂伝統的建造物群保存地区」がある場所はどこか。', '嵐山地区', '東山・清水坂周辺', '西陣地区', '祇園四条周辺', 1, '産寧坂（さんねいざか/さんねんざか）伝統的建造物群保存地区は東山区清水寺周辺に位置し、石畳の坂道と伝統的な町家・商家が残る景観が保護されています。重要伝統的建造物群保存地区（重伝建）に指定されています。', 1, false),
(5, 21, '「祇園新橋伝統的建造物群保存地区」の特徴として正しいのはどれか。', '武家屋敷が連続する地区', '花街の茶屋建築が並ぶ地区', '西陣織の機屋（はたや）が集中する地区', '商家の蔵が連続する地区', 1, '祇園新橋伝統的建造物群保存地区は東山区の白川・新橋通沿いに位置し、花街の茶屋建築（置屋・茶屋）が連続して残る景観が保護されています。重要伝統的建造物群保存地区（重伝建）に指定されています。', 2, false),
(5, 21, '京町家で「火袋（ひぶくろ）」とはどのような空間か。', '囲炉裏の周囲の空間', '通り庭上部の吹き抜け空間', '台所の換気口', '炭小屋', 1, '火袋（ひぶくろ）は通り庭（土間）の上部に設けられた吹き抜け空間で、かまどや囲炉裏の煙を逃がすとともに採光の役割も果たします。京町家の暗くなりがちな内部に光を取り込む伝統的な知恵のひとつです。', 2, false),
(5, 21, '京都の町家の屋根に多く使われる瓦の色として最も一般的なのはどれか。', '赤色', '黒色（銀黒）', '緑色', '白色', 1, '京都の町家の屋根には黒色（銀黒色）の「いぶし瓦（本瓦）」や桟瓦が多く使われています。この落ち着いた黒みがかった瓦の連続が京都の町並み景観を特徴づけています。', 1, false),
(5, 21, '「町家の路地（ろじ）」とはどのような場所か。', '茶室へ向かう露地庭園', '町家の間を抜ける細い共有通路', '市場の通り', '神社への参道', 1, '路地（ろじ）は複数の町家の間を抜ける細い私道・共有通路のことで、京都の市街地に多く残っています。奥まった場所に複数の住居が集まる「路地に面した町家」が京都独特の住宅コミュニティを形成してきました。', 2, false),
(5, 21, '京都市が京町家の数を定期的に調査しているが、2016年時点でその数はおよそ何棟か。', '約5万棟', '約8万棟', '約15万棟', '約25万棟', 0, '2016年の調査によると京都市内の京町家は約4万7000棟と報告されました（一部は約5万棟超の報告もあり）。毎年800〜900棟が減少しているとされており、保全が急務とされています。', 3, false),
(5, 21, '「伝統的建造物群保存地区（重伝建）」の指定権限を持つ機関はどこか。', '文化庁', '国土交通省', '京都市が単独で指定', '市町村が申し出・国が選定', 3, '重要伝統的建造物群保存地区（重伝建）は市町村が条例で保存地区を指定・申し出し、文部科学大臣（文化庁）が「重要」として選定します。両者の手続きによって正式に指定される制度です。', 3, false),
(5, 21, '西陣地区の町家に多い「織屋建て（おりやだて）」の特徴はどれか。', '屋根が低く平屋構造', '2階に大型の機（はた）を置くための構造で天井が高い', '蔵を中心に設計された構造', '茶室を内包した構造', 1, '織屋建て（おりやだて）は西陣の機業（はたや）に見られる建築形式で、2階に大型の織機を設置するため天井が非常に高く造られているのが特徴です。西陣独特の建築様式として京都の重要な文化的景観を形成しています。', 3, false),
(5, 21, '京都市内で最も多くの重要伝統的建造物群保存地区を持つ区はどれか。', '中京区', '東山区', '上京区', '北区', 1, '東山区は産寧坂（三年坂）・祇園新橋の重要伝統的建造物群保存地区を有しており、京都市内でも特に多くの伝統的建造物が保護されています。東山の自然環境と合わさって京都の歴史的景観を代表する地区です。', 2, false);

